WITH inventory_summary AS ( SELECT inv_warehouse_sk, SUM(inv_quantity_on_hand) AS total_inventory_on_hand FROM inventory WHERE inv_date_sk BETWEEN 2450815 AND 2451053 GROUP BY inv_warehouse_sk ), sales_agg AS ( SELECT s.web_name, s.web_state, w.w_warehouse_sk, w.w_warehouse_name, w.w_city, sm.sm_type, sm.sm_carrier, COUNT(DISTINCT ws.ws_order_number) AS order_count, SUM(ws.ws_quantity) AS total_quantity_sold, SUM(ws.ws_net_paid) AS total_net_paid, SUM(ws.ws_net_profit) AS total_net_profit, AVG(ws.ws_net_profit) AS avg_net_profit FROM web_sales ws JOIN web_site s ON ws.ws_web_site_sk = s.web_site_sk JOIN warehouse w ON ws.ws_warehouse_sk = w.w_warehouse_sk JOIN ship_mode sm ON ws.ws_ship_mode_sk = sm.sm_ship_mode_sk WHERE s.web_country = 'United States' AND w.w_country = 'United States' AND sm.sm_type IN ('EXPRESS', 'OVERNIGHT') AND ws.ws_sold_date_sk BETWEEN 2450815 AND 2451053 GROUP BY s.web_name, s.web_state, w.w_warehouse_sk, w.w_warehouse_name, w.w_city, sm.sm_type, sm.sm_carrier HAVING SUM(ws.ws_net_profit) > 5000 ) SELECT sa.web_name AS site_name, sa.web_state AS site_state, sa.w_warehouse_name AS warehouse_name, sa.w_city AS warehouse_city, sa.sm_type AS ship_mode_type, sa.sm_carrier AS carrier, sa.order_count, sa.total_quantity_sold, sa.total_net_paid, sa.total_net_profit, sa.avg_net_profit, COALESCE(isum.total_inventory_on_hand, 0) AS total_inventory_on_hand FROM sales_agg sa LEFT JOIN inventory_summary isum ON isum.inv_warehouse_sk = sa.w_warehouse_sk ORDER BY total_net_profit DESC LIMIT 15
